tools.parameters:
{
      type: 'object',
      properties: {
        format: {
          type: 'string',
          description: '可选：image（默认，发面板图）或 text（发 6 行文字卡）。用户明确说要文字时才传 text。'
        }
      }
    }

{
        type: 'object',
        properties: {
          count: { type: 'number', description: '看最近多少条，默认 15，最多 50。' },
          onlyResponded: { type: 'boolean', description: '只看判定为「要接」的记录。' }
        }
      }

{
      type: 'object',
      properties: {
        action: { type: 'string', enum: ['checkin', 'status'], description: 'checkin 领取今天的签到金币；status 查询本人签到状态与规则。' },
        userId: { type: 'string', pattern: '^[1-9]\\d{4,11}$', description: 'status 可选，只能填本人 QQ 号；不接受昵称。' },
        messageId: { type: 'string', pattern: '^(?:-?\\d+|local:[1-9]\\d*)$', description: '提出签到的那条本轮真实消息编号，来自聊天记录；没有 QQ 编号时用 local:本地编号。' }
      },
      required: ['action'],
      additionalProperties: false
    }

{
      type: 'object',
      properties: {
        query: { type: 'string', description: '检索词：把问题里最关键的人名/名词/说法放进来' },
        kb: { type: 'string', description: '可选：只查某一本库，填库的 id 或名字（不确定就留空）' },
        limit: { type: 'integer', description: '最多返回几条，默认用设置里的值', minimum: 1, maximum: 20 }
      },
      required: ['query']
    }

{
      type: 'object',
      properties: {
        kb: { type: 'string', description: '库的 id 或名字' },
        maxChars: { type: 'integer', description: '最多读多少字，默认 1500', minimum: 100, maximum: 6000 }
      },
      required: ['kb']
    }

{
      type: 'object',
      properties: {
        server: { type: 'string', description: '可选。只看某一个服务，例如 github。' }
      }
    }

{
      type: 'object',
      properties: {
        server: { type: 'string', description: '服务名（mcp_list 里括号前的那个）。同名工具只在一个服务里时可省略。' },
        tool: { type: 'string', description: '工具名，例如 read_file / search_repositories。' },
        arguments: { type: 'object', description: '工具参数对象，按 inputSchema 填。没有参数就留空。' }
      },
      required: ['tool']
    }

{
      type: 'object',
      properties: {
        url: { type: 'string', description: '要读取的 http(s) 链接' }
      },
      required: ['url']
    }

{
      type: 'object',
      properties: {
        image: { type: 'string', description: 'http(s) 图片地址；省略则用本会话最近一张收到的图片' }
      }
    }

{
      type: 'object',
      properties: {
        keyword: { type: 'string', description: '游戏名或 appid。留空则从触发原文里取。' }
      }
    }

{
      type: 'object',
      properties: {
        note: {
          type: 'string',
          description: '这个表情包/图片的含义与适用场合，一句话，例如「举白旗的猫，服软认错时用」。'
        },
        scope: {
          type: 'string',
          enum: ['chat', 'global'],
          description: 'chat = 只在当前会话复用（表情包在本群有特定用法时选它）；global = 所有会话通用（默认）。'
        },
        overwrite: {
          type: 'boolean',
          description: '留空或 false 时，库里已有含义就不覆盖（只记第一次的理解）；true = 用这次的覆盖旧含义（群友纠正过的情形）。'
        }
      },
      required: ['note']
    }

{
